def build(path,title,description,content,active=''):
 depth=0 if path=='index.html' or '/' not in path else len(Path(path).parts)-1
 base='../'*depth
 def href(v):return base+(v.lstrip('/') or 'index.html')
 def navlink(label,target,key):return f'<a href="{href(target)}"'+(' aria-current="page"' if active==key else '')+f'>{label}</a>'
 navigation=navlink('Services','services/','services')+navlink('Industries','industries/','industries')+navlink('About','about/','about')+navlink('Contact','contact/','contact')
 canonical='https://cybranixsystems.com/'+('' if path=='index.html' else path.replace('index.html',''))
 body=f'''<a class="skip" href="#main">Skip to content</a>
<header><div class="wrap header-inner"><a class="brand" href="{href('')}" aria-label="CYBRANIX LLC home"><span class="brand-mark">C</span><span>CYBRANIX <small>LLC</small></span></a><nav aria-label="Main navigation">{navigation}<a class="button primary header-cta" href="{href('contact/')}">Book an Introductory Call <span aria-hidden="true">&gt;</span></a></nav></div></header>
<main id="main">{content}</main>
<footer><div class="wrap footer-grid"><div><a class="brand" href="{href('')}">CYBRANIX <small>LLC</small></a><p>Technology direction.<br>Organized delivery. Lasting capability.</p></div><div><strong>Explore</strong>{navigation}</div><div><strong>Start a conversation</strong><a href="mailto:{EMAIL}">{EMAIL}</a><a href="tel:+17793791260">(779) 379-1260</a><a href="{href('industries/government/')}">Government &amp; Public Sector</a></div></div><div class="wrap footer-bottom"><span>© 2026 CYBRANIX LLC</span><span>Founder-led. Built around your goals.</span></div></footer>'''
 # Placeholder prefix works at every GitHub Pages depth, including project subpaths.
 body=body.replace('@@',base)
 data={'@context':'https://schema.org','@type':'Organization','name':'CYBRANIX LLC','url':'https://cybranixsystems.com/','email':EMAIL,'telephone':'+17793791260'}
 text=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#102d3b"><title>{escape(title)} | CYBRANIX LLC</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | CYBRANIX LLC"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta name="twitter:card" content="summary"><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}styles.css"><script type="application/ld+json">{json.dumps(data)}</script></head><body>{body}</body></html>'''
 f=ROOT/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(text.replace('><','>\n<'))

def button(text='Book an Introductory Call',target='contact/',kind='primary'):
 return f'<a class="button {kind}" href="@@{target}">{text} <span aria-hidden="true">&gt;</span></a>'
def ending(title='Bring your next technology priority into focus.'):
 return f'<section class="contact-section"><div class="wrap closing"><div><p class="eyebrow">A PRACTICAL NEXT STEP</p><h2>{title}</h2><p>Tell us what you want to improve. We’ll discuss fit, scope, and the right place to start.</p></div>{button()}</div></section>'
def intro(eyebrow,title,desc):
 return f'<section class="page-hero"><div class="wrap"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lede">{desc}</p></div></section>'
def servicecards(items=SERVICES):
 return '<div class="link-grid">'+''.join(f'<article class="link-card"><span class="service-no">{i+1:02d} / SERVICE</span><h3><a href="@@services/{s[0]}/">{s[1]}</a></h3><p>{s[3]}</p><a class="text-link" href="@@services/{s[0]}/">Explore service <span aria-hidden="true">&gt;</span></a></article>' for i,s in enumerate(items))+'</div>'
def industrycards(items=INDUSTRIES):
 return '<div class="industry-grid">'+''.join(f'<a class="industry-link" href="@@industries/{i[0]}/"><span>{i[1]}</span><span aria-hidden="true">&gt;</span></a>' for i in items)+'</div>'
def listitems(items):return '<ul class="plain-list">'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'

