 content=intro(name.upper(),headline,desc)+f'<section class="section wrap detail-grid"><div><p class="eyebrow">POTENTIAL ENGAGEMENTS</p><h2>Start with the work<br>that needs structure.</h2>{listitems(activities)}</div><aside class="deliverable-panel"><h3>Shaped to your environment.</h3><p>{note}</p><p>Engage for a defined project or an agreed advisory scope. The size of your organization does not determine whether we can have a useful conversation.</p></aside></section>'+extra+f'<section class="section wrap"><p class="eyebrow">EXPLORE RELEVANT SUPPORT</p><h2>Services that connect to your priorities.</h2>{servicecards([SERVICES[0],SERVICES[1],SERVICES[3 if j%2==0 else 5]])}<a class="text-link" href="@@industries/">Back to all industries &gt;</a></section>'+ending()
